// Drizzle schema. Every change ships with a committed migration generated by `pnpm db:generate`.
//
// Auth-related tables follow Better Auth's core schema: Drizzle *property* names are the
// Better Auth field names (e.g. `name`, `emailVerified`), while *column* names are snake_case.
import { sql } from 'drizzle-orm';
import { check, index, integer, primaryKey, sqliteTable, text, uniqueIndex } from 'drizzle-orm/sqlite-core';
import { USER_STATUSES, WORKSPACE_ROLES } from '@vergissmeinnicht/domain';

const timestampMs = (column: string) =>
  integer(column, { mode: 'timestamp_ms' })
    .notNull()
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`);

/**
 * Internal Users. `id` is the stable internal identity; login methods (password, TOTP,
 * future Apple/GitHub) are linked to it by separate tables and never replace it.
 */
export const users = sqliteTable(
  'users',
  {
    id: text('id').primaryKey(),
    /** Display name (Better Auth field `name`). */
    name: text('display_name').notNull(),
    /** Normalized email; see `normalizeEmail` in the domain package. */
    email: text('email').notNull().unique(),
    emailVerified: integer('email_verified', { mode: 'boolean' }).notNull().default(false),
    /** Better Auth core field. Not rendered anywhere until a reviewed use exists (see security.md §5). */
    image: text('image'),
    status: text('status', { enum: USER_STATUSES }).notNull().default('ACTIVE'),
    /** Server-wide admin flag (application-owned; must be `input: false` in Better Auth). */
    serverAdmin: integer('server_admin', { mode: 'boolean' }).notNull().default(false),
    createdAt: timestampMs('created_at'),
    updatedAt: timestampMs('updated_at'),
  },
  (table) => [
    // Defense in depth behind application-side validation.
    check('users_id_uuid', sql`length(${table.id}) = 36`),
    check('users_email_normalized', sql`${table.email} = lower(trim(${table.email})) and length(${table.email}) <= 254`),
    check('users_display_name_present', sql`length(trim(${table.name})) > 0`),
    check(
      'users_status_valid',
      sql.raw(`status in (${USER_STATUSES.map((status) => `'${status}'`).join(', ')})`),
    ),
  ],
);

/**
 * Better Auth sessions (model `session`, `modelName: 'sessions'`). The cookie carries
 * `token` plus an HMAC signature keyed by AUTH_SECRET, so the stored token alone cannot be
 * replayed as a cookie. Server-side state is authoritative: deleting the row ends the session.
 */
export const sessions = sqliteTable(
  'sessions',
  {
    id: text('id').primaryKey(),
    token: text('token').notNull().unique(),
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    expiresAt: integer('expires_at', { mode: 'timestamp_ms' }).notNull(),
    /** Client address as seen by the server (proxy trust per docu/security.md §11); never from client headers. */
    ipAddress: text('ip_address'),
    userAgent: text('user_agent'),
    createdAt: timestampMs('created_at'),
    updatedAt: timestampMs('updated_at'),
  },
  (table) => [index('sessions_user_id_idx').on(table.userId)],
);

/**
 * Better Auth accounts (model `account`, `modelName: 'accounts'`): linked authentication methods
 * of an internal User. `providerId = 'credential'` holds the Argon2id password hash; future
 * Apple/GitHub identities become further rows and never replace `users.id`.
 */
export const accounts = sqliteTable(
  'accounts',
  {
    id: text('id').primaryKey(),
    /** Provider subject. For `credential` it is the internal User id. */
    accountId: text('account_id').notNull(),
    providerId: text('provider_id').notNull(),
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    accessToken: text('access_token'),
    refreshToken: text('refresh_token'),
    idToken: text('id_token'),
    accessTokenExpiresAt: integer('access_token_expires_at', { mode: 'timestamp_ms' }),
    refreshTokenExpiresAt: integer('refresh_token_expires_at', { mode: 'timestamp_ms' }),
    scope: text('scope'),
    /** Argon2id PHC string; only for `credential` rows. */
    password: text('password'),
    createdAt: timestampMs('created_at'),
    updatedAt: timestampMs('updated_at'),
  },
  (table) => [
    index('accounts_user_id_idx').on(table.userId),
    // One identity per provider subject: an external account can never be attached to two Users.
    uniqueIndex('accounts_provider_account_unique').on(table.providerId, table.accountId),
    check(
      'accounts_credential_shape',
      sql`${table.providerId} <> 'credential' or (${table.accountId} = ${table.userId} and ${table.password} like '$argon2id$%')`,
    ),
  ],
);

/**
 * Better Auth verification values (model `verification`, `modelName: 'verifications'`). Required
 * by Better Auth's schema check; no V1 flow writes to it (email verification and password reset
 * by email are disabled). Any future use must store only hashed or short-lived values.
 */
export const verifications = sqliteTable(
  'verifications',
  {
    id: text('id').primaryKey(),
    identifier: text('identifier').notNull(),
    value: text('value').notNull(),
    expiresAt: integer('expires_at', { mode: 'timestamp_ms' }).notNull(),
    createdAt: timestampMs('created_at'),
    updatedAt: timestampMs('updated_at'),
  },
  (table) => [index('verifications_identifier_idx').on(table.identifier)],
);

/**
 * TOTP credentials, one per user. `secret` is sealed with AES-256-GCM (key from
 * DATA_ENCRYPTION_KEY, bound to the user id). `enabled_at IS NULL` = unconfirmed enrollment.
 */
export const totpCredentials = sqliteTable(
  'totp_credentials',
  {
    userId: text('user_id')
      .primaryKey()
      .references(() => users.id, { onDelete: 'cascade' }),
    sealedSecret: text('sealed_secret').notNull(),
    createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
    enabledAt: integer('enabled_at', { mode: 'timestamp_ms' }),
    /** Replay protection: highest accepted RFC 6238 time step. */
    lastUsedStep: integer('last_used_step').notNull().default(-1),
    consecutiveFailures: integer('consecutive_failures').notNull().default(0),
    lockedUntil: integer('locked_until', { mode: 'timestamp_ms' }),
  },
  (table) => [
    check('totp_credentials_sealed_format', sql`${table.sealedSecret} like 'v1.%'`),
    check('totp_credentials_failures_non_negative', sql`${table.consecutiveFailures} >= 0`),
  ],
);

/** Single-use recovery codes; only SHA-256 hashes of the 80-bit codes are stored. */
export const recoveryCodes = sqliteTable(
  'recovery_codes',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => totpCredentials.userId, { onDelete: 'cascade' }),
    codeHash: text('code_hash').notNull().unique(),
    createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
    usedAt: integer('used_at', { mode: 'timestamp_ms' }),
  },
  (table) => [
    index('recovery_codes_user_id_idx').on(table.userId),
    check('recovery_codes_hash_format', sql`length(${table.codeHash}) = 64`),
  ],
);

/**
 * Pending sign-ins of TOTP-enabled accounts (password verified, second factor outstanding).
 * The client holds the raw token in a cookie; only its SHA-256 hash is stored. No session exists
 * until the challenge is completed.
 */
export const mfaChallenges = sqliteTable(
  'mfa_challenges',
  {
    id: text('id').primaryKey(),
    tokenHash: text('token_hash').notNull().unique(),
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
    expiresAt: integer('expires_at', { mode: 'timestamp_ms' }).notNull(),
    attempts: integer('attempts').notNull().default(0),
    consumedAt: integer('consumed_at', { mode: 'timestamp_ms' }),
  },
  (table) => [
    index('mfa_challenges_user_id_idx').on(table.userId),
    check('mfa_challenges_token_hash_format', sql`length(${table.tokenHash}) = 64`),
    check('mfa_challenges_expiry_after_creation', sql`${table.expiresAt} > ${table.createdAt}`),
  ],
);

/**
 * Admin- or operator-initiated account recoveries. Only a SHA-256 hash of the link token is stored;
 * the link goes to the account's own email address (or the operator's terminal).
 */
export const accountRecoveries = sqliteTable(
  'account_recoveries',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    tokenHash: text('token_hash').notNull().unique(),
    resetPassword: integer('reset_password', { mode: 'boolean' }).notNull(),
    resetTotp: integer('reset_totp', { mode: 'boolean' }).notNull(),
    /** NULL = issued by the operator CLI. */
    issuedByUserId: text('issued_by_user_id').references(() => users.id),
    createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
    expiresAt: integer('expires_at', { mode: 'timestamp_ms' }).notNull(),
    completedAt: integer('completed_at', { mode: 'timestamp_ms' }),
    revokedAt: integer('revoked_at', { mode: 'timestamp_ms' }),
  },
  (table) => [
    index('account_recoveries_user_id_idx').on(table.userId),
    check('account_recoveries_scope', sql`${table.resetPassword} = 1 or ${table.resetTotp} = 1`),
    check('account_recoveries_token_hash_format', sql`length(${table.tokenHash}) = 64`),
    check('account_recoveries_expiry_after_creation', sql`${table.expiresAt} > ${table.createdAt}`),
    check('account_recoveries_single_outcome', sql`${table.completedAt} is null or ${table.revokedAt} is null`),
    check('account_recoveries_not_self_issued', sql`${table.issuedByUserId} is null or ${table.issuedByUserId} <> ${table.userId}`),
  ],
);

/** Invitations. Only a SHA-256 hash of the link token is stored. */
export const invitations = sqliteTable(
  'invitations',
  {
    id: text('id').primaryKey(),
    email: text('email').notNull(),
    tokenHash: text('token_hash').notNull().unique(),
    grantsServerAdmin: integer('grants_server_admin', { mode: 'boolean' }).notNull().default(false),
    /** NULL = issued by the CLI bootstrap. */
    invitedByUserId: text('invited_by_user_id').references(() => users.id),
    createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
    expiresAt: integer('expires_at', { mode: 'timestamp_ms' }).notNull(),
    acceptedAt: integer('accepted_at', { mode: 'timestamp_ms' }),
    acceptedUserId: text('accepted_user_id').references(() => users.id),
    revokedAt: integer('revoked_at', { mode: 'timestamp_ms' }),
    revokedByUserId: text('revoked_by_user_id').references(() => users.id),
  },
  (table) => [
    index('invitations_email_idx').on(table.email),
    check('invitations_email_normalized', sql`${table.email} = lower(trim(${table.email}))`),
    check('invitations_token_hash_format', sql`length(${table.tokenHash}) = 64`),
    check('invitations_expiry_after_creation', sql`${table.expiresAt} > ${table.createdAt}`),
    check('invitations_single_outcome', sql`${table.acceptedAt} is null or ${table.revokedAt} is null`),
    check(
      'invitations_accepted_user_consistent',
      sql`(${table.acceptedAt} is null) = (${table.acceptedUserId} is null)`,
    ),
  ],
);

/**
 * Workspaces: the collaboration and security boundary. Never hard-deleted by the application
 * (historical Runs will reference them); foreign keys to it do not cascade.
 */
export const workspaces = sqliteTable(
  'workspaces',
  {
    id: text('id').primaryKey(),
    name: text('name').notNull(),
    createdByUserId: text('created_by_user_id')
      .notNull()
      .references(() => users.id),
    createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
    updatedAt: integer('updated_at', { mode: 'timestamp_ms' }).notNull(),
  },
  (table) => [
    check('workspaces_id_uuid', sql`length(${table.id}) = 36`),
    check('workspaces_name_present', sql`length(trim(${table.name})) > 0`),
  ],
);

/**
 * Memberships: one role per User and Workspace. Removal deletes the row (recorded as a
 * MEMBERSHIP_REMOVED security event); every authorization reads this table, so it takes effect
 * on the next request.
 */
export const memberships = sqliteTable(
  'memberships',
  {
    workspaceId: text('workspace_id')
      .notNull()
      .references(() => workspaces.id),
    userId: text('user_id')
      .notNull()
      .references(() => users.id),
    role: text('role', { enum: WORKSPACE_ROLES }).notNull(),
    createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
    updatedAt: integer('updated_at', { mode: 'timestamp_ms' }).notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.workspaceId, table.userId] }),
    index('memberships_user_id_idx').on(table.userId),
    check(
      'memberships_role_valid',
      sql.raw(`role in (${WORKSPACE_ROLES.map((role) => `'${role}'`).join(', ')})`),
    ),
  ],
);

/**
 * Append-only security event log (UPDATE/DELETE blocked by triggers in migration 0002).
 * Metadata is JSON and must never contain secrets.
 */
export const securityEvents = sqliteTable(
  'security_events',
  {
    id: text('id').primaryKey(),
    occurredAt: integer('occurred_at', { mode: 'timestamp_ms' }).notNull(),
    type: text('type').notNull(),
    actorUserId: text('actor_user_id').references(() => users.id),
    /** Display-name snapshot for users, or the system channel label (e.g. `cli:admin-bootstrap`). */
    actorLabel: text('actor_label').notNull(),
    subjectType: text('subject_type').notNull(),
    subjectId: text('subject_id').notNull(),
    metadata: text('metadata', { mode: 'json' }).$type<Record<string, string | number | boolean>>(),
  },
  (table) => [
    index('security_events_subject_idx').on(table.subjectType, table.subjectId),
    index('security_events_occurred_at_idx').on(table.occurredAt),
  ],
);
